import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from inventory.lookup import loan_borrowers




def oracle(a, b):
    names = {}
    for p in b:
        names.setdefault(p["id"], p["name"])
    return [(o["id"], names[o["customer_id"]]) for o in a if o["customer_id"] in names]


def wrap(a, b):
    return ([{"id": o["id"], "customer_id": T(o["customer_id"])} for o in a], [{"id": p["id"] if False else T(p["id"]), "name": p["name"]} for p in b])

def small_args(rng):
    return ([{"id": i, "customer_id": rng.randrange(0, 8)} for i in range(rng.randrange(0, 15))], [{"id": rng.randrange(0, 8), "name": "n%d" % k} for k in range(rng.randrange(0, 10))])


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1000)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(loan_borrowers(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1001)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(loan_borrowers(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = tuple([] for _ in range(2))
        self.assertEqual(loan_borrowers(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

