import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from inventory.lookup import loan_borrowers




def oracle(a, b):
    names = {}
    for p in b:
        names.setdefault(p["id"], p["name"])
    return [(o["id"], names[o["customer_id"]]) for o in a if o["customer_id"] in names]


def wrap(a, b):
    return ([{"id": o["id"], "customer_id": T(o["customer_id"])} for o in a], [{"id": p["id"] if False else T(p["id"]), "name": p["name"]} for p in b])

def big_args(rng, n):
    return ([{"id": i, "customer_id": rng.randrange(0, n)} for i in range(n)], [{"id": rng.randrange(0, n), "name": "n%d" % k} for k in range(n)])


class PerformanceTests(unittest.TestCase):
    def test_cost_grows_with_the_input(self):
        rng = random.Random(1000)
        n = 1000
        args = big_args(rng, n)
        wrapped = wrap(*copy.deepcopy(args))
        limit = 30 * n
        Ops.reset()
        Ops.budget = limit * 20
        try:
            got = loan_borrowers(*wrapped)
        except BudgetExceeded:
            self.fail("PERF: gave up after %d comparisons and hash calls for %d items (limit %d): the function scans lists instead of using hash lookups" % (Ops.budget, n, limit))
        finally:
            Ops.budget = None
        ops = Ops.total()
        self.assertEqual(plain(got), oracle(*copy.deepcopy(args)))
        self.assertLessEqual(ops, limit, "PERF: %d comparisons and hash calls for %d items (limit %d): the function scans lists instead of using hash lookups" % (ops, n, limit))

