"""inventory: small helpers used by the batch jobs."""


def loan_borrowers(loans, members):
    """Pair every loan with the borrower's name."""
    names = {}
    for person in members:
        names.setdefault(person["id"], person["name"])
    out = []
    for order in loans:
        if order["customer_id"] in names:
            out.append((order["id"], names[order["customer_id"]]))
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

