        rng = random.Random(1002)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(duplicate_scans(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = tuple([] for _ in range(1))
        self.assertEqual(duplicate_scans(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

