import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from gatehouse.scan import tidy_catalogue




def oracle(a):
    counts = {}
    for x in a:
        counts[x] = counts.get(x, 0) + 1
    u = list(counts)
    return {"unique": u, "repeats": [x for x in u if counts[x] > 1]}


def wrap(a):
    return ([T(x) for x in a],)

def small_args(rng):
    return ([rng.randrange(0, 10) for _ in range(rng.randrange(0, 25))],)


class CorrectnessTests(unittest.TestCase):
