def compare_inventory(expected, counted):
    """Compare the expected stock ids with the ids found in the stock take."""
    matched = [x for x in expected if x in counted]
    missing = [x for x in expected if x not in counted]
    extra = []
    for y in counted:
        if y not in expected:
            extra.append(y)
    return {"matched": matched, "missing": missing, "extra": extra}


